export function evaluateConfidence(consistencyScores, threshold) {
  const lowConfidenceFlags = consistencyScores.filter(score => score < threshold);
  return {
    flagged: lowConfidenceFlags.length > 0,
    flaggedScores: lowConfidenceFlags
  };
}

export function multiPathEvaluation(paths, threshold) {
  const consistencyScores = paths.map(path => path.consistencyScore);
  return evaluateConfidence(consistencyScores, threshold);
}